package com.ebank.chatbot.web;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

final class Requests {

    private Requests() {}

    /** @param clientMessageId generated by the client (a UUID is fine); a retry with the same one is stored once */
    record SendMessage(
            @NotBlank @Pattern(regexp = "[A-Za-z0-9_-]{8,64}") String clientMessageId,
            @NotBlank @Size(max = 2000) String text) {}

    record MarkRead(@NotNull @Min(0) Long seq) {}
}
